  // State WAIT_READY: ready_o = 0. If ready_i (from dst), go to SEND.
  // State SEND: ready_o = 1, valid_o = 1. If ready_i (from dst), go to IDLE.

  always_ff @(posedge src_clk_i or negedge src_rst_ni) begin
