            src_data_reg <= src_data_i;
            src_state <= GRAB;
          end
          src_ready_o <= 1'b1;
        end
        GRAB: begin
          if (src_valid_i) begin
            src_ready_o <= 1'b0;
          end else begin
            src_ready_o <= 1'b1;
          end
        end
        SEND: begin
          src_ready_o <= 1'b1;
          src_valid_reg <= 1'b1;
        end
